text.reverse-index-scroll:
  ...probe("text.reverse-index-scroll", (ctx) => {
    if (!validSize(ctx.getScrollback().screenLines, 5)) {
      return {
        pass: false,
        observation: { outcome: "inconclusive", reason: "insufficient-evidence", evidence: "none" }
      };
    }
    try {
      ctx.feed("\x1B[1;5r");
      ctx.feed("\x1B[H");
      ctx.feed("MARKER");
      const before = ctx.getCell(0, 0);
      ctx.feed("\x1B[H");
      ctx.feed("\x1BM");
      const cell = ctx.getCell(1, 0);
      return parserStateResult(before.char === "M" ? cell.char === "M" : null, "RI moves the measured MARKER to row 2", { before, cell }, before.char === "M" ? undefined : "MARKER control was not measured");
    } finally {
      ctx.feed("\x1B[r");
    }
  }, async (ctx) => {
    const refusal = tooSmall(ctx, 10, 1);
    if (refusal)
      return refusal;
    try {
      ctx.write("\x1B[3;10r");
      ctx.write("\x1B[3;1H");
      ctx.write("\x1BM");
      const pos = await ctx.queryCursorPosition();
      return unmeasuredCellResult(pos, "RI scrolling of region contents");
    } finally {
      ctx.write("\x1B[r");
    }
  }),
  termNeedsGeometry: true
},

reset.method:
  ...probe("reset.method", (ctx) => {
    ctx.feed("Hello World");
    const before = { ...ctx.getCursor(), text: ctx.getText() };
    ctx.reset();
    const after = { ...ctx.getCursor(), text: ctx.getText() };
    const expected = "Reset method returns the cursor home and clears measured text";
    if (!before.text.includes("Hello World") || before.x === 0) {
      return parserStateResult(null, expected, { before, after }, "Reset-method control state was not measured");
    }
    return parserStateResult(after.x === 0 && after.y === 0 && !after.text.includes("Hello World"), expected, {
      before,
      after
    });
  }, () => {
    const note = "The app context has no reset() method or equivalent state readback";
    return Promise.resolve({
      pass: false,
      note,
      observation: {
        outcome: "inconclusive",
        reason: "insufficient-evidence",
        evidence: "none",
        note
      }
    });
  })
}

extensions.osc1-icon:
  ...probe("extensions.osc1-icon", (ctx) => {
    const before = ctx.getTitle();
    ctx.feed("\x1B]1;test-icon\x07");
    const after = ctx.getTitle();
    return notTestedResult("icon-name state", { before, after });
  }, () => {
    const note = "No icon-name readback for OSC 1";
    return Promise.resolve({
      pass: false,
      note,
      observation: { outcome: "inconclusive", reason: "insufficient-evidence", evidence: "none", note }
    });
  }),
  termlessObservationEvidence: "parser-state"
},
